$root='G:\源文件\自动同步'; $configPath=Join-Path $PSScriptRoot 'tiktok-automation.config.json'; $settingsPath=Join-Path $root '自动任务设置.json'; $node='C:\Program Files\nodejs\node.exe'; $job=Join-Path $PSScriptRoot 'tiktok-daily-job.js'; $storeUpdater=Join-Path $PSScriptRoot 'automation-store-config.js'; $prefix='TikTokShop自动下载并导入-'
function Read-Config { $raw=Get-Content -Raw $configPath; if(!$raw.Trim()){throw '店铺配置为空，已停止加载以保护已有店铺信息。'}; $data=$raw|ConvertFrom-Json; if(!$data.shopMappings){$data|Add-Member -NotePropertyName shopMappings -NotePropertyValue @()}; return $data }
function Write-Config($c){if(!$c){throw '未读取到店铺配置，已拒绝保存。'};$temp="$configPath.tmp";[IO.File]::WriteAllText($temp,($c|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));Move-Item -LiteralPath $temp -Destination $configPath -Force}
function Store-Key($s){if($s.profileKey){[string]$s.profileKey}else{'default'}}
function Task-Name($s){$prefix+(Store-Key $s)}
function Refresh-Status { $tasks=@(Get-ScheduledTask -ErrorAction SilentlyContinue|Where-Object{$_.TaskName -like "$prefix*"}); if(!$tasks.Count){'未启用自动化'}else{"已启用 $($tasks.Count) 家店铺"} }
function Save-Tasks($time,$c){Get-ScheduledTask -ErrorAction SilentlyContinue|Where-Object{$_.TaskName -like "$prefix*"}|ForEach-Object{Unregister-ScheduledTask -TaskName $_.TaskName -Confirm:$false}; foreach($s in @($c.shopMappings|Where-Object{$_.automationEnabled -ne $false})){ $key=Store-Key $s; $cmd='"'+$node+'" "'+$job+'" --store "'+$key+'" >> "'+(Join-Path $root '自动任务.log')+'" 2>&1'; $a=New-ScheduledTaskAction -Execute 'C:\Windows\System32\cmd.exe' -Argument ('/c '+$cmd); $t=New-ScheduledTaskTrigger -Daily -At ([datetime]::ParseExact($time,'HH:mm',$null)); $p=New-ScheduledTaskPrincipal -UserId ("$env:USERDOMAIN\$env:USERNAME") -LogonType Interactive -RunLevel Limited; Register-ScheduledTask -TaskName (Task-Name $s) -Action $a -Trigger $t -Principal $p -Description "自动同步 $($s.systemShopCode)" -Force|Out-Null}; [IO.File]::WriteAllText($settingsPath,(@{time=$time}|ConvertTo-Json),[Text.UTF8Encoding]::new($false))}
$configRef=[pscustomobject]@{Value=(Read-Config)}; try{$setting=Get-Content -Raw $settingsPath|ConvertFrom-Json}catch{$setting=[pscustomobject]@{time='09:30'}}
